guardrails.body:
{
  "id": "measured-player",
  "name": "Require a current Watergirl position",
  "denyWhen": {
    "all": [
      {
        "field": "action.action",
        "op": "ne",
        "value": "wait"
      },
      {
        "field": "observed.watergirl.confidence",
        "op": "lt",
        "value": 0.9
      }
    ]
  },
  "onUnknown": "deny",
  "message": "Watergirl position is missing or unreliable. Observe before moving."
}

{
  "id": "bounded-walk",
  "name": "Limit each ordinary walk",
  "denyWhen": {
    "all": [
      {
        "any": [
          {
            "field": "action.action",
            "op": "eq",
            "value": "left"
          },
          {
            "field": "action.action",
            "op": "eq",
            "value": "right"
          }
        ]
      },
      {
        "field": "action.durationMs",
        "op": "gt",
        "value": 600
      }
    ]
  },
  "onUnknown": "deny",
  "message": "Use a shorter walking action, then inspect fresh state."
}
